import datetime, json
# A quantum-readiness policy as a machine-readable document with a validator. DEMO DATA: invented organisation and objectives.
POLICY = {
    "title": "Quantum-readiness policy", "version": "1.0", "approved_by": "CISO", "next_review": "2027-09-30",
    "objectives": [
        {"id": "O1", "statement": "Maintain a cryptographic inventory covering all internet-facing and tier 1 assets", "owner": "Head of Security Architecture", "due": "2027-03-31", "kpi": "inventory coverage of tier 1 assets", "target": 1.0, "review": "quarterly"},
        {"id": "O2", "statement": "Migrate key establishment of tier 1 assets to hybrid post-quantum", "owner": "Platform lead", "due": "2028-12-31", "kpi": "share of tier 1 assets with hybrid key establishment", "target": 1.0, "review": "quarterly"},
        {"id": "O3", "statement": "Be crypto-agile", "owner": None, "due": None, "kpi": None, "target": None, "review": None},
        {"id": "O4", "statement": "Retire classical-only key exchange on internet-facing services", "owner": "Network lead", "due": "2031-06-30", "kpi": "share of classical-only connections", "target": 0.01, "review": "semi-annual"},
    ],
}
TODAY = datetime.date(2027, 1, 15)          # fixed so that the output is reproducible
REVIEW = {"quarterly", "semi-annual", "annual"}
def validate(policy):
    problems = []
    for o in policy["objectives"]:
        w = []
        if not o["owner"]: w.append("no owner")
        if not o["due"]: w.append("no due date")
        elif datetime.date.fromisoformat(o["due"]) < TODAY: w.append("due date already passed")
        if not o["kpi"] or o["target"] is None: w.append("not measurable (no KPI or target)")
        if o["review"] not in REVIEW: w.append("no review cadence")
        problems.append((o["id"], w))
    return problems
print(f"policy '{POLICY['title']}' v{POLICY['version']}, approved by {POLICY['approved_by']}, next review {POLICY['next_review']}")
print(f"{'id':<4} {'owner':<30} {'due':<11} {'review':<12} result")
for (oid, w), o in zip(validate(POLICY), POLICY["objectives"]):
    print(f"{oid:<4} {str(o['owner']):<30} {str(o['due']):<11} {str(o['review']):<12} {'OK' if not w else 'REJECTED: ' + '; '.join(w)}")
ok = [o for o in POLICY["objectives"] if not dict(validate(POLICY))[o["id"]]]
print()
print(f"{len(ok)} of {len(POLICY['objectives'])} objectives are enforceable as written")
print("O3 'Be crypto-agile' fails every test: nobody owns it, nothing dates it, nothing measures it, and nobody reviews it; rewritten it could read: 'All new systems use the approved crypto API (E4.2); share of cryptographic call sites behind the boundary reaches 90% by 2028-06-30; owner: Software architecture lead; reviewed semi-annually'")
print()
print("consistency of dates against the programme (dates from the lesson plan; policy dates quoted in E1.1 are drafts):")
for o in ok:
    d = datetime.date.fromisoformat(o["due"])
    print(f"  {o['id']} due {o['due']}: {'before the proposed 2030 deprecation of 112-bit RSA/ECDSA (IR 8547 draft)' if d.year < 2030 else 'after 2030: confirm that the exposure until then is accepted by the risk owner'}")
print("a policy is useful when each sentence can be tested: an objective without owner, date and measure is an aspiration, not a control")

import datetime
# Risk ownership register with automatic checks. DEMO DATA: invented people, assets and risks; "today" is fixed for reproducibility.
TODAY = datetime.date(2027, 6, 1)
STAFF = {"alice": "active", "bob": "active", "carol": "left the company 2027-04-30", "dan": "active"}
ASSETS = {"customer portal": "alice", "claims upload": "bob", "legacy ERP": None, "HR archive": "carol", "internal PKI": "dan", "HSM": "dan"}
RISKS = [
    {"id": "R1", "text": "HR archive wrapped under RSA key, 40-year secrecy requirement", "asset": "HR archive", "owner": "carol", "due": "2027-05-01", "status": "open"},
    {"id": "R2", "text": "Claims upload uses RSA key transport", "asset": "claims upload", "owner": "bob", "due": "2027-09-30", "status": "open"},
    {"id": "R3", "text": "Legacy ERP: algorithms unknown", "asset": "legacy ERP", "owner": None, "due": None, "status": "open"},
    {"id": "R4", "text": "HSM firmware cannot sign with ML-DSA", "asset": "HSM", "owner": "dan", "due": "2027-05-15", "status": "open"},
    {"id": "R5", "text": "PKI root migration plan", "asset": "internal PKI", "owner": "dan", "due": "2027-12-31", "status": "in progress"},
]
def check_risk(r):
    issues = []
    if r["owner"] is None: issues.append("NO OWNER")
    elif STAFF.get(r["owner"]) != "active": issues.append(f"owner {r['owner']} is not active ({STAFF.get(r['owner'])})")
    if r["due"] is None: issues.append("no due date")
    elif r["status"] != "closed" and datetime.date.fromisoformat(r["due"]) < TODAY: issues.append(f"OVERDUE by {(TODAY - datetime.date.fromisoformat(r['due'])).days} days")
    return issues
print(f"date of the check: {TODAY}")
print(f"{'risk':<4} {'asset':<16} {'owner':<7} {'due':<11} {'status':<12} findings")
escalate = []
for r in RISKS:
    f = check_risk(r)
    print(f"{r['id']:<4} {r['asset']:<16} {str(r['owner']):<7} {str(r['due']):<11} {r['status']:<12} {'; '.join(f) or 'ok'}")
    if f: escalate.append((r["id"], f))
print()
print("assets without an accountable active owner:", [a for a, o in ASSETS.items() if o is None or STAFF.get(o) != "active"])
print()
print("escalation rule applied (written policy): an issue older than 30 days goes to the CISO; no owner or an inactive owner goes to the CISO immediately; a risk with an issue and tier 1 data goes to the risk committee")
for rid, f in escalate:
    days = max([int(x.split("by ")[1].split(" ")[0]) for x in f if x.startswith("OVERDUE")] + [0])
    target = "CISO immediately" if any(("NO OWNER" in x or "not active" in x) for x in f) else "CISO (overdue more than 30 days)" if days > 30 else f"owner reminded, no escalation yet ({days} days overdue)"
    print(f"  {rid}: {target}")
print()
print("a RACI is a table of who is Responsible, Accountable, Consulted and Informed. For this register: Accountable = the risk owner named above (one person, never a team alias); Responsible = the team doing the work; Consulted = security architecture; Informed = the risk committee. A role with two accountable names has none")
